mapper.select:
SELECT s.stock_code, s.stock_name, s.market, sp.stock_date, sp.open_price, sp.close_price, sp.low_price, sp.high_price, sp.price_change, sp.volume FROM stock_price as sp JOIN stock_info as s on sp.stock_code = s.stock_code WHERE sp.stock_code = #{stockCode}
AND sp.stock_date >= #{startDate}
AND sp.stock_date <= #{endDate}
ORDER BY sp.stock_date ASC
